#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

    /// Returns the longest character sequence in `strings`, or `None` if the list is empty.
    /// If there are multiple sequences of the same maximum length, returns the one
    /// at the smallest index.
    fn longest(strings: Vec<Vec<char>>) -> Option<Vec<char>>
        ensures
            // If we return None, the input must have been empty.
            match result {
                None =>
                    strings.len() == 0,
                Some(ref v) => {
                    // Otherwise, there is some index ′max_idx′ witnessing that
                    // 1) v exactly equals strings[max_idx],
                    // 2) v has length >= every other string in the input, and
                    // 3) for all j < max_idx, strings[j].len() < v.len().
                    exists |max_idx: nat|
                        max_idx < strings.len() &&
                        *v == strings[max_idx] &&
                        forall |i: nat| i < strings.len() ==> strings[i].len() <= v.len() &&
                        forall |i: nat| i < max_idx     ==> strings[i].len() <  v.len()
                }
            }
    {
        // Handle the empty‐input case immediately.
        if strings.len() == 0 {
            return None;
        }

        // We know there is at least one element.
        let mut best_idx: nat = 0;
        let mut idx:      nat = 1;

        // Scan the array, maintaining that:
        //  ─── for all i < idx, strings[i].len() <= strings[best_idx].len()
        //  ─── for all i < best_idx, strings[i].len() <  strings[best_idx].len()
        while idx < strings.len()
            invariant idx <= strings.len()
            invariant forall |i: nat| i < idx      ==> strings[i].len() <= strings[best_idx].len()
            invariant forall |i: nat| i < best_idx ==> strings[i].len() <  strings[best_idx].len()
            decreases strings.len() - idx
        {
            if strings[idx].len() > strings[best_idx].len() {
                best_idx = idx;
            }
            idx += 1;
        }

        // Return a clone of the chosen sequence.
        // (We clone because we still need `strings` in our post‐state
        //  to talk about the ensures‐clause.)
        Some(strings[best_idx].clone())
    }

}